#include <print>
#include <string>
#include <map>

int main() {
    for (std::string s : {std::string("bbbbb"), std::string("pwwkew"), std::string("abcabcbb")}) {
        std::map<char, int> cnt;
        int left = 0, best = 0;
        for (int right = 0; right < static_cast<int>(s.size()); ++right) {
            ++cnt[s[right]];                         // 右端吃进一个字符
            while (cnt[s[right]] > 1) { --cnt[s[left]]; ++left; }   // 撞了就从左端吐
            int w = right - left + 1;
            if (w > best) best = w;                  // 合规了才量宽度
            std::println("  {}     {}     {}     {}     {}", right, s[right], left, best, s.substr(left, w));
        }
        std::println("{} 最长不重复段 = {}", s, best);
    }
    return 0;
}
// 跟一遍 abcabcbb：left 那一列是 0 0 0 1 2 3 5 7，一路往上走

