#include <map>

int main() {
    std::string s = "abcabcbb";
    std::map<char, int> cnt;
    int left = 0, best = 0;
    for (int right = 0; right < static_cast<int>(s.size()); ++right) {
        ++cnt[s[right]];
        while (cnt[s[right]] > 1) { --cnt[s[left]]; ++left; }
        if (right - left + 1 > best) best = right - left + 1;
    }
    std::println("最长不重复段 = {}", best);
    return 0;
}
